// Model źle liczy daty ("za 3 dni", "w piątek"), więc dostaje gotowy kalendarz liczony tutaj (Luxon, strefa workflow = Europe/Warsaw).
const DNI = ['poniedziałek', 'wtorek', 'środa', 'czwartek', 'piątek', 'sobota', 'niedziela'];
const now = $now.setZone('Europe/Warsaw');
const lines = [];
for (let i = 0; i < 120; i++) {
  const d = now.plus({ days: i });
  const label = i === 0 ? 'dziś' : i === 1 ? 'jutro' : i === 2 ? 'pojutrze' : `za ${i} dni`;
  lines.push(`${d.toFormat('yyyy-MM-dd')} ${DNI[d.weekday - 1]} (${label}), przesunięcie ${d.set({ hour: 12 }).toFormat('ZZ')}`);
}
return [{ json: {
  teraz: `${now.toFormat('yyyy-MM-dd HH:mm')} (${DNI[now.weekday - 1]}), strefa Europe/Warsaw, przesunięcie ${now.toFormat('ZZ')}`,
  kalendarz: lines.join('\n'),
} }];

const r = $input.first().json;
const fail = (status, error) => [{ json: { result: { status, error } } }];
if ((!($json).choices && /\b402\b|insufficient credits|more credits/i.test(JSON.stringify(($json).error || $json)))) return fail(402, "Mam chwilową przerwę — skończył się limit, z którego korzystam. Łukasz już o tym wie.");   // tekst i test: n8n/komunikaty.py
if (r.error) return fail(502, 'Model nie odpowiedział — spróbuj jeszcze raz.');
let m;
try { m = JSON.parse(String(r.choices?.[0]?.message?.content || '').replace(/^```(json)?|```$/g, '').trim()); } catch { m = null; }
if (!m || !Array.isArray(m.parts)) return fail(502, 'Nie udało mi się tego rozebrać na części — spróbuj jeszcze raz.');
const cut = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
const parts = m.parts.map((p) => ({ text: cut(p?.text, 1000), from: cut(p?.from, 120) })).filter((p) => p.text.length >= 3).slice(0, 30);
return [{ json: { result: { status: 200, parts, skipped: cut(m.skipped, 400) } } }];
